/** The events `GET /feed` carries, discriminated by the frame's `event:` field. */
export type FeedEvent =
  | { event: "invoice_paid"; data: InvoicePaid }
  | { event: "invoice_voided"; data: InvoiceVoided };

function reviveCostNode(v: CostNode): CostNode {
  return { ...v, price: reviveMoney(v.price), discount: reviveMoney(v.discount), children: (v.children).map((x0) => reviveCostNode(x0)) };
}

function reviveFeedItem(v: FeedItem): FeedItem {
  if (v != null && typeof v === "object" && "Ack" in v) return { ...v, Ack: reviveInt64(v.Ack) };
  return v;
}

function reviveInvoicePaid(v: InvoicePaid): InvoicePaid {
  return { ...v, amount_cents: reviveInt64(v.amount_cents) };
}

function reviveInvoiceView(v: InvoiceView): InvoiceView {
  return { ...v, totalCents: reviveInt64(v.totalCents), sequence: reviveInt64(v.sequence), lineItems: (v.lineItems).map((x0) => reviveLineItem(x0)), payment: revivePayment(v.payment), notice: reviveNotification(v.notice), lastItem: reviveFeedItem(v.lastItem), adjustmentCents: (v.adjustmentCents) == null ? null : (reviveInt64(v.adjustmentCents)), lateFeeCents: (v.lateFeeCents) == null ? (v.lateFeeCents) : (reviveInt64(v.lateFeeCents)), installmentCents: (v.installmentCents).map((x0) => reviveInt64(x0)), feesByCategory: Object.fromEntries(Object.entries(v.feesByCategory).map(([k0, x0]) => [k0, reviveInt64(x0)])), refundBatchesCents: (v.refundBatchesCents) == null ? null : ((v.refundBatchesCents).map((x0) => reviveInt64(x0))), disputedLineCents: (v.disputedLineCents).map((x0) => (x0) == null ? null : (reviveInt64(x0))), ...(v.creditNoteCents === undefined ? {} : { creditNoteCents: (v.creditNoteCents) == null ? null : (reviveInt64(v.creditNoteCents)) }) };
}

function reviveLimitExceeded(v: LimitExceeded): LimitExceeded {
  return { ...v, maxCents: reviveInt64(v.maxCents) };
}

function reviveLineItem(v: LineItem): LineItem {
  return { ...v, unitAmountCents: reviveInt64(v.unitAmountCents) };
}

function reviveMoney(v: Money): Money {
  return { ...v, cents: reviveInt64(v.cents) };
}

function reviveNotification(v: Notification): Notification {
  if (v["kind-of"] === "Progress") return { ...v, payload: { ...v.payload, bytes_done: reviveInt64(v.payload.bytes_done) } };
  return v;
}

function revivePayment(v: Payment): Payment {
  if (v.type === "Card") return { ...v, limit_cents: reviveInt64(v.limit_cents) };
  return v;
}

export class Api extends ApiBase {
  /** Requires a session token: call `setToken` first. */
  async createCustomer(id: CustomerId, body: CreateCustomerBody): Promise<Result<CustomerView, ApiError>> {
    return this.request<CustomerView, ApiError>("POST", `/customers/${encodeURIComponent(id)}`, body);
  }

  async getInvoice(id: InvoiceId): Promise<Result<InvoiceView, ApiError>> {
    const r = await this.request<InvoiceView, ApiError>("GET", `/invoices/${encodeURIComponent(id)}`);
    return r.ok ? { ok: true, data: reviveInvoiceView(r.data) } : { ok: false, error: r.error };
  }

  async listInvoices(): Promise<Result<(InvoiceView)[], ApiError>> {
    const r = await this.request<(InvoiceView)[], ApiError>("GET", "/invoices");
    return r.ok ? { ok: true, data: (r.data).map((x0) => reviveInvoiceView(x0)) } : { ok: false, error: r.error };
  }

  async adjustInvoice(id: InvoiceId, body: AdjustInvoiceBody): Promise<Result<InvoiceView, ApiError>> {
    const r = await this.request<InvoiceView, ApiError>("POST", `/invoices/${encodeURIComponent(id)}/adjust`, body);
    return r.ok ? { ok: true, data: reviveInvoiceView(r.data) } : { ok: false, error: r.error };
  }

  async withdrawInvoice(id: InvoiceId): Promise<Result<InvoiceView, LimitExceeded>> {
    const r = await this.request<InvoiceView, LimitExceeded>("POST", `/invoices/${encodeURIComponent(id)}/withdraw`);
    return r.ok ? { ok: true, data: reviveInvoiceView(r.data) } : { ok: false, error: reviveLimitExceeded(r.error) };
  }

  async lastItem(id: InvoiceId): Promise<Result<FeedItem, ApiError>> {
    const r = await this.request<FeedItem, ApiError>("GET", `/invoices/${encodeURIComponent(id)}/last-item`);
    return r.ok ? { ok: true, data: reviveFeedItem(r.data) } : { ok: false, error: r.error };
  }

  async costTree(): Promise<Result<CostNode, ApiError>> {
    const r = await this.request<CostNode, ApiError>("GET", "/cost-tree");
    return r.ok ? { ok: true, data: reviveCostNode(r.data) } : { ok: false, error: r.error };
  }

  async deleteWidget(id: WidgetId): Promise<Result<null, ApiError>> {
    return this.request<null, ApiError>("DELETE", `/widgets/${encodeURIComponent(id)}`);
  }

  /** Requires a session token: call `setToken` first. */
  feed(opts: SubscribeOptions<FeedEvent>): Promise<void> {
    return this.stream<FeedEvent>("/feed", opts, new Map([["invoice_paid", (d: unknown) => reviveInvoicePaid(d as InvoicePaid)], ["invoice_voided", null]]));
  }

  rawFeed(opts: SubscribeOptions<UnknownEvent>): Promise<void> {
    return this.stream<UnknownEvent>("/raw-feed", opts);
  }
}
